    "Loading team agents...": "正在加载团队智能体…",
    "Agent blocked": "智能体已阻塞",
    "The agent needs your help before setup can continue. Complete or skip the blocking tasks to keep going.": "智能体需要你的帮助才能继续设置。请完成或跳过阻塞任务后继续。",
    "Agent disconnected": "智能体已断开连接",
