    "Couldn't load this agent. It may have been deleted, or the server couldn't find it.": "无法加载此智能体。它可能已被删除，或服务器未找到它。",
    "You are not authorized to access this agent's files.": "你无权访问此智能体的文件。",
    "You are not authorized to access this agent's terminal.": "你无权访问此智能体的终端。",
    "You are not authorized to access this agent's desktop.": "你无权访问此智能体的桌面。",
    "Working on a Long Task?": "正在处理长时间任务？",
    "Continue in Cloud": "在云端继续",
    "Continuing in Cloud…": "正在转到云端继续…",
    "Still running locally?": "仍在本地运行？",
    "Connection looks slow": "连接似乎较慢",
    "Continue running in Cloud?": "要在云端继续运行吗？",
    "Move to Cloud to keep running longer without your computer open.": "转到云端，无需一直开着电脑即可运行更久。",
    "Move to Cloud so the agent can keep running even if you disconnect.": "转到云端，即使连接断开，智能体也能继续运行。",
    "Move this agent to the Cloud to run longer without your computer open.": "将此智能体转到云端，无需一直开着电脑即可运行更久。",
    "Review this external prompt carefully before proceeding": "继续前请仔细检查此外部提示词",
    "Undo & Apply will undo all previously applied chats before applying this one.": "“撤销并应用”会撤销此前所有已应用的对话更改，然后再应用当前更改。",
    "Cloud agents require all workspace folders to be inside a Git repository.": "所有工作区文件夹都必须位于 Git 仓库中，才能使用云端智能体。",
    "Pin limit reached. Unpin an agent to pin another.": "已达到置顶上限。请取消置顶一个智能体后再置顶其他智能体。",
    "Failed to start Cloud Agent": "启动云端智能体失败",
    "AWS Access Key ID": "AWS 访问密钥 ID",
    "Access Key ID": "访问密钥 ID",
