    "Secret Access Key": "秘密访问密钥",
    "No commit has been scored yet": "尚未对提交进行 AI 内容评分",
    "E.g. Build me a multiplayer game of tictactoe using express and React": "例如，使用 Express 和 React 为我构建一个井字棋多人游戏",
    "Upload image": "上传图像",
    "PNG, JPEG, or WebP...": "PNG、JPEG 或 WebP…",
    "Link 1": "链接 1",
    "When enabled, your cursor.com profile page is visible to anyone with the link.": "启用后，任何获得链接的人都可以查看你的 cursor.com 个人资料页面。",
    "Run Everything": "全部允许",
    "Enabled by Run Everything Auto-Run Mode: Agent bypasses approval prompts for tools including Web Search.": "已启用“全部允许”自动运行模式：智能体将跳过包括网页搜索在内的工具审批提示。",
    "All commands will run without approval, classification or sandboxing.": "所有命令都将直接运行，不经过审批、分类或沙箱。",
    "Choose GitHub or Graphite for pull request links on web and desktop": "选择在网页端和桌面端使用 GitHub 或 Graphite 打开拉取请求链接",
    "Mark Agent commits as 'Made with Cursor'": "将智能体提交标记为“Made with Cursor”",
    "Mark pull requests as made with Cursor": "将拉取请求标记为由 Cursor 创建",
    "Browser Automation": "浏览器自动化",
    "Browser automation disabled": "浏览器自动化已关闭",
    "Browser Protection": "浏览器保护",
    "Prevent Agent from automatically running Browser tools": "阻止智能体自动运行浏览器工具",
    "Open Local Links in Cursor Browser": "在 Cursor 浏览器中打开本地链接",
    "Open Web Links in Cursor Browser": "在 Cursor 浏览器中打开网页链接",
    "Copy Domains": "复制域名",
    "Run Diagnostic": "运行诊断",
    "Apply .cursorignore files to all subdirectories. Changing this setting requires restarting Cursor.": "将 .cursorignore 文件应用到所有子目录。更改此设置后需要重启 Cursor。",
    "Use with caution. Skip symlinks during .cursorignore file discovery. Enable only when all .cursorignore files are reachable without symlinks. Changing this setting requires restarting Cursor.": "请谨慎使用。查找 .cursorignore 文件时跳过符号链接。仅当所有 .cursorignore 文件无需通过符号链接即可访问时启用。更改此设置后需要重启 Cursor。",
    "By default, get notifications for stable updates. In Early Access, pre-release builds may be unstable for production work": "默认接收稳定版更新通知。抢先体验版为预发布构建，可能不适合生产环境。",
    "Automate repetitive tasks with always-on agents and configure Cursor's built-in agents for your team.": "使用持续运行的智能体自动处理重复任务，并为团队配置 Cursor 内置智能体。",
    "Automations use Cloud Agents, which require us to give agents access to your codebase. This is not compatible with Legacy Privacy Mode.": "自动化功能使用云端智能体，因此需要授予智能体访问代码库的权限。此功能与旧版隐私模式不兼容。",
    "Edit Privacy Settings": "编辑隐私设置",
    "Abort Agent and Restore Query": "中止智能体并恢复查询",
    "Active workspace references": "活动工作区引用",
    "Add a custom MCP tool in your Home MCP config.": "在个人 MCP 配置中添加自定义 MCP 工具。",
    "Add a personal cloud MCP server to make it available to your cloud agents.": "添加个人云端 MCP 服务器，供云端智能体使用。",
