    "The auto-fix setting cannot be toggled while Cascade is running.": "Cascade 运行时无法切换自动修复设置。",
    "The bundled Devin agent is not reachable right now. Unsaved edits are kept and can be saved once it is running again.": "当前无法连接随附的 Devin 智能体。未保存的编辑会保留，恢复运行后即可保存。",
