    "The connection failed. Try again, or run the command below.": "连接失败。请重试或运行以下命令。",
    "The file changes that will be applied as a result of this revert are not available for preview.": "无法预览此次还原将应用的文件更改。",
    "The file should contain one secret per line in Key=Value format.": "文件应每行包含一个密钥，格式为 Key=Value。",
    "The following files have been modified since the merge and cannot be automatically reverted:": "以下文件在合并后已被修改，无法自动还原：",
