    "The license file was not accepted.": "许可证文件未被接受。",
    "The models file changed on disk since it was loaded, so saving would overwrite those changes. Reload to pick them up, then re-apply your edits.": "模型文件加载后已在磁盘上发生变化，保存会覆盖这些变化。请重新加载后再次编辑。",
    "The models file exists but could not be read, so it cannot be edited here. Fix the file on disk (check permissions and encoding), then reload.": "模型文件存在但无法读取，因此不能在此编辑。请检查磁盘文件的权限和编码，修复后重新加载。",
